package main

import (
	"fmt"
	"io/ioutil"
	"os"
)

func main() {
	file, err := os.Open("input.txt")
	if err != nil {
		logError(err)
		return
	}
	defer file.Close()

	content, err := ioutil.ReadAll(file)
	if err != nil {
		logError(err)
		return
	}

	fmt.Println(string(content))
}

func logError(err error) {
	// Implementa un registro seguro aquí
	fmt.Fprintf(os.Stderr, "Error: %v\n", err)
}

