codigo_parchado:
from flask import Flask, request
import ast
app = Flask(__name__)

@app.route('/eval', methods=['POST'])
def evaluate():
    data = request.get_data()
    try:
        # Usar ast.literal_eval para evaluar expresiones seguras
        result = ast.literal_eval(data.decode('utf-8'))
        return str(result)
    except (ValueError, SyntaxError):
        return 'Invalid input', 400

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)

codigo_original:
#include <iostream>

class Resource {
public:
    Resource() { std::cout << "Resource acquired\n"; }
    ~Resource() { std::cout << "Resource destroyed\n"; }
};

Resource* getResource() {
    return new Resource();
}

void useResource(Resource* r) {
    if (r != nullptr) {
        std::cout << "Using resource\n";
    } else {
        std::cout << "No resource to use\n";
    }
}

int main() {
    Resource* r = getResource();
    useResource(r);
    delete r;
    useResource(r); // This will cause a use-after-free error
    return 0;
}

codigo_parchado:
#include <iostream>

class Resource {
public:
    Resource() { std::cout << "Resource acquired\n"; }
    ~Resource() { std::cout << "Resource destroyed\n"; }
};

Resource* getResource() {
    return new Resource();
}

void useResource(Resource* r) {
    if (r != nullptr) {
        std::cout << "Using resource\n";
    } else {
        std::cout << "No resource to use\n";
    }
}

int main() {
    Resource* r = getResource();
    useResource(r);
    delete r;
    // Evita el uso después de liberar
    r = nullptr;
    useResource(r);
    return 0;
}

