public class SecureClass implements Serializable {
    private String command;

    public SecureClass(String command) {
        this.command = command;
    }

    private void readObject(ObjectInputStream stream) throws Exception {
        stream.defaultReadObject();
        // Evita la ejecución de comandos externos
        throw new UnsupportedOperationException("Deserialización remota insegura")
    }

    public static void main(String[] args) {
        try {
            ByteArrayOutputStream bos = new ByteArrayOutputStream();
            ObjectOutputStream oos = new ObjectOutputStream(bos);
            SecureClass payload = new SecureClass("calc");
            oos.writeObject(payload);
            oos.close();

