from subprocess import run

def execute_user_input():
    user_input = input("Enter your command: ")
    # Sanitize the user input to prevent SSRF
    if all(char.isalnum() or char.isspace() for char in user_input):
        # Use a whitelist of allowed commands instead of running arbitrary commands
        allowed_commands = ['ls', 'pwd']
        if user_input in allowed_commands:
            run(user_input, shell=False, check=True)
        else:
            print("Invalid command. Only specific commands are allowed.")
    else:
        print("Invalid input. Only alphanumeric characters and spaces are allowed.")

