package main

import (
	"fmt"
	"os"
)

func main() {
	var length int
	fmt.Println("Enter the length of the slice: ")
	_, err := fmt.Scan(&length)
	if err != nil || length < 0 {
		fmt.Fprintln(os.Stderr, "Invalid input")
		os.Exit(1)
	}

	// Limit the length to avoid buffer overflow
	const maxLen = 1000
	if length > maxLen {
		length = maxLen
	}

	s := make([]int, length)

	for i := 0; i < length; i++ {
		s[i] = i
	}

	fmt.Println(s)
}

