codigo_parchado:
from pickle import dumps, loads
from subprocess import run

class SafePickle:
    def __reduce__(self):
        raise TypeError('Pickling is not allowed')

def serialize_and_deserialize(obj):
    if isinstance(obj, SafePickle):
        raise ValueError('Serialization of SafePickle objects is not allowed')
    serialized = dumps(obj)
    deserialized = loads(serialized)
    return deserialized

if __name__ == '__main__':
    try:
        serialize_and_deserialize(SafePickle())
    except Exception as e:
        print(e)

