@app.route('/calculate', methods=['POST'])
def calculate():
    data = request.form.get('data')

    # Check if data is None
    if data is None:
        return make_response("No data provided", 400)

    # Parse the data into an AST (Abstract Syntax Tree)
    try:
        tree = ast.parse(data, mode='eval')
    except SyntaxError:
        return make_response("Invalid syntax", 400)

    # Ensure the tree only contains literals and containers
    allowed_types = {ast.Expression, ast.Num, ast.Str, ast.Bytes, ast.NameConstant, ast.List, ast.Tuple, ast.Dict, ast.BinOp, ast.UnaryOp, ast.Compare, ast.Call}
    for node in ast.walk(tree):
        if type(node) not in allowed_types:
            return make_response("Invalid operation", 400)

    # Evaluate the expression safely using a whitelist of functions
    def safe_eval(expr):
        def restricted_globals():
            return {
                '__builtins__': None,
                'abs': abs,
                'max': max,
                'min': min,
                'sum': sum,
                'len': len,
                'int': int,
                'float': float,
                'str': str,
                'bool': bool,
                'None': None,
                'True': True,
                'False': False,
            }
        return eval(expr, restricted_globals())

    result = safe_eval(compile(tree, filename='', mode='eval'))

    return "Result: {}
".format(result)

if __name__ == '__main__':
    app.run()

