package main

import "fmt"

func main() {
	// Create a slice with a length of 2 and a capacity of 3
	slice := make([]int, 2, 3)

	// Add elements to the slice
	slice[0] = 1
	slice[1] = 2

	// Check if there is enough space before appending
	if len(slice)+1 > cap(slice) {
		newSlice := make([]int, len(slice), len(slice)*2)
		copy(newSlice, slice)
		slice = newSlice
	}

	// Append the element safely
	slice = append(slice, 3)

	// Print the slice
	fmt.Println(slice)
}

